/**
 * Pangram domain tools: AI-writing detection and original-source search.
 *
 * Two questions about a text that its content alone cannot answer: was it
 * written by a person or generated by a model, and does it match content
 * already on the web? Pangram answers both over its REST API:
 *
 *   pangram_check_ai      POST {API}/task, then poll GET {API}/task/{id}
 *   pangram_find_sources  POST {PLAGIARISM_API} (synchronous)
 *
 * The endpoints and payloads follow Pangram's own Python SDK
 * (pangram-sdk 1.0.0, pangram/text_classifier.py).
 *
 * Every call costs real money, billed by the word, so the contract mirrors
 * the Elicit adapter (elicit-tools.ts): the tools exist only when a
 * PANGRAM_API_KEY is configured, the text sent is capped at
 * pangramMaxWords, each bundle carries a per-run call cap, and every call
 * Pangram accepted is metered into llm_usage like any other external spend.
 * Failures degrade gracefully (§20): an error tool-result the agent routes
 * around, never a crashed run.
 *
 * Null-delegate convention: `execute` returns null for any other tool name,
 * so an agent wires the bundle with one spread and one early return.
 */
import type Anthropic from "@anthropic-ai/sdk";
type Tool = Anthropic.Tool;
import { loadConfig, type Config } from "../../config.js";
import { meterExternalUsage } from "../../services/usage-service.js";
import { readPage } from "../../services/source-watch-service.js";

export const PANGRAM_TOOL_PREFIX = "pangram_";
export const PANGRAM_CHECK_AI_TOOL_NAME = "pangram_check_ai";
export const PANGRAM_FIND_SOURCES_TOOL_NAME = "pangram_find_sources";

const SUCCESS_STAGE = "STAGE_SUCCESS";
const FAILED_STAGE = "STAGE_FAILED";
/** Per-request HTTP timeout; the plagiarism search is slower than a submit. */
const REQUEST_TIMEOUT_MS = 15_000;
const PLAGIARISM_TIMEOUT_MS = 90_000;
/** How long one detection may take end to end before the tool gives up. */
const DETECTION_DEADLINE_MS = 60_000;
const POLL_INTERVAL_MS = 1_000;
/** Bounds on what goes back into the agent's context. */
const MAX_WINDOWS_RETURNED = 6;
const MAX_SOURCES_RETURNED = 8;
const EXCERPT_CHARS = 240;

/** Whether the Pangram tools are configured at all (deploy-level switch). */
export function pangramConfigured(config: Config = loadConfig()): boolean {
  return !!config.pangramApiKey;
}

/**
 * Whether the Steward run for a claim of this importance should be offered
 * the Pangram tools. Like Elicit's gate (§19): a per-word fee is not worth
 * paying on every minor claim.
 */
export function pangramEnabledForImportance(
  importance: number,
  config: Config = loadConfig()
): boolean {
  return pangramConfigured(config) && importance >= config.stewardPangramMinImportance;
}

export function isPangramTool(name: string): boolean {
  return name === PANGRAM_CHECK_AI_TOOL_NAME || name === PANGRAM_FIND_SOURCES_TOOL_NAME;
}

const textOrUrlSchema = {
  type: "object" as const,
  properties: {
    text: {
      type: "string",
      description: "The passage to analyze. Give this or url, not both.",
    },
    url: {
      type: "string",
      description:
        "A public page to read and analyze instead of pasting its text (read as by read_page).",
    },
  },
};

export function getPangramToolDefinitions(config: Config = loadConfig()): Tool[] {
  if (!pangramConfigured(config)) return [];
  const cap = `Only the first ${config.pangramMaxWords} words are sent.`;
  const per100 = (usdPerWord: number) =>
    `Billed ${+(usdPerWord * 100 * 100).toFixed(2)}¢ per 100 words.`;
  return [
    {
      name: PANGRAM_CHECK_AI_TOOL_NAME,
      description:
        "Pangram's AI-writing detection: classifies a text as human-written, " +
        "AI-generated, AI-assisted, or mixed. Returns the overall verdict, the " +
        "fraction of the text in each class, and the most AI-like passages " +
        `with their scores and confidence. ${per100(config.pangramAiUsdPerWord)} ${cap}`,
      input_schema: textOrUrlSchema,
    },
    {
      name: PANGRAM_FIND_SOURCES_TOOL_NAME,
      description:
        "Pangram's plagiarism check: searches the web for content matching a " +
        "text. Returns whether matching content was found, the share of the " +
        "text that matches, and the matching sources with their urls. " +
        `${per100(config.pangramPlagiarismUsdPerWord)} ${cap}`,
      input_schema: textOrUrlSchema,
    },
  ];
}

/** Words in a text, counted as Pangram bills them (whitespace-delimited). */
export function countWords(text: string): number {
  const trimmed = text.trim();
  return trimmed ? trimmed.split(/\s+/).length : 0;
}

/** The text cut to its first `maxWords` words, whitespace preserved. */
export function truncateToWords(text: string, maxWords: number): string {
  const trimmed = text.trim();
  if (maxWords <= 0) return trimmed;
  const re = /\S+/g;
  let match: RegExpExecArray | null;
  let n = 0;
  while ((match = re.exec(trimmed)) !== null) {
    n += 1;
    if (n === maxWords) return trimmed.slice(0, match.index + match[0].length);
  }
  return trimmed;
}

function excerpt(value: unknown): string {
  const s = typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  return s.length > EXCERPT_CHARS ? `${s.slice(0, EXCERPT_CHARS)}…` : s;
}

function failure(message: string): string {
  return JSON.stringify({ success: false, message });
}

/** Resolve the input to the text to send, or an error message. */
async function resolveText(
  input: Record<string, unknown>
): Promise<{ text: string; url: string | null } | { error: string }> {
  const text = typeof input.text === "string" ? input.text.trim() : "";
  const url = typeof input.url === "string" ? input.url.trim() : "";
  if (text && url) return { error: "Give text or url, not both." };
  if (text) return { text, url: null };
  if (!url) return { error: "text or url is required." };
  const page = await readPage(url);
  if (!page.ok) return { error: `Could not read ${url}: ${page.problem}` };
  return { text: page.text.replace(/\n\[truncated\]$/, ""), url };
}

async function pangramFetch(
  url: string,
  init: { method: "GET" | "POST"; body?: unknown; timeoutMs: number },
  config: Config
): Promise<Record<string, unknown>> {
  const res = await fetch(url, {
    method: init.method,
    headers: {
      "x-api-key": config.pangramApiKey,
      ...(init.body !== undefined ? { "Content-Type": "application/json" } : {}),
    },
    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
    signal: AbortSignal.timeout(init.timeoutMs),
  });
  const raw = await res.text();
  if (!res.ok) throw new Error(`Pangram returned ${res.status}: ${raw.slice(0, 300)}`);
  let json: unknown;
  try {
    json = JSON.parse(raw);
  } catch {
    throw new Error(`Pangram returned a non-JSON response: ${raw.slice(0, 300)}`);
  }
  if (!json || typeof json !== "object" || Array.isArray(json)) {
    throw new Error("Pangram returned an unexpected response shape");
  }
  const obj = json as Record<string, unknown>;
  if ("error" in obj) throw new Error(`Pangram returned an error: ${String(obj.error)}`);
  return obj;
}

function meter(tool: string, words: number, usdPerWord: number): Promise<void> {
  return meterExternalUsage({
    provider: "pangram",
    model: `pangram/${tool}`,
    units: words,
    unitKind: "words",
    costMicroUsd: words * usdPerWord * 1_000_000,
  });
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

async function checkAi(
  text: string,
  url: string | null,
  config: Config,
  wait: (ms: number) => Promise<void>
): Promise<string> {
  const words = countWords(text);
  const submitted = await pangramFetch(
    `${config.pangramApiUrl}/task`,
    {
      method: "POST",
      body: { text, model: config.pangramModel, public_dashboard_link: false },
      timeoutMs: REQUEST_TIMEOUT_MS,
    },
    config
  );
  const taskId = submitted.task_id;
  if (typeof taskId !== "string" || !taskId) {
    throw new Error("Pangram accepted the text but returned no task_id");
  }
  // The task was accepted, so it is billed, whatever happens while polling.
  await meter("check_ai", words, config.pangramAiUsdPerWord);

  const deadline = Date.now() + DETECTION_DEADLINE_MS;
  for (;;) {
    const result = await pangramFetch(
      `${config.pangramApiUrl}/task/${encodeURIComponent(taskId)}`,
      { method: "GET", timeoutMs: REQUEST_TIMEOUT_MS },
      config
    );
    if (result.stage === SUCCESS_STAGE) return JSON.stringify(summarizeAi(result, words, url));
    if (result.stage === FAILED_STAGE) {
      throw new Error(`detection failed: ${String(result.headline ?? result.detail ?? "no detail")}`);
    }
    if (Date.now() >= deadline) {
      throw new Error(`detection did not finish within ${DETECTION_DEADLINE_MS / 1000}s`);
    }
    await wait(POLL_INTERVAL_MS);
  }
}

/** The detection result, cut down to what a judgment needs. */
export function summarizeAi(
  result: Record<string, unknown>,
  wordsSent: number,
  url: string | null
): Record<string, unknown> {
  const windows = Array.isArray(result.windows) ? (result.windows as Array<Record<string, unknown>>) : [];
  const score = (w: Record<string, unknown>) =>
    typeof w.ai_assistance_score === "number" ? w.ai_assistance_score : 0;
  const passages = [...windows]
    .sort((a, b) => score(b) - score(a))
    .slice(0, MAX_WINDOWS_RETURNED)
    .map((w) => ({
      label: w.label,
      ai_assistance_score: w.ai_assistance_score,
      confidence: w.confidence,
      ...(typeof w.is_humanized === "boolean" ? { is_humanized: w.is_humanized } : {}),
      excerpt: excerpt(w.text),
    }));
  return {
    success: true,
    ...(url ? { url } : {}),
    words_analyzed: wordsSent,
    model_version: result.version,
    verdict: result.prediction_short,
    headline: result.headline,
    prediction: result.prediction,
    fraction_ai: result.fraction_ai,
    fraction_ai_assisted: result.fraction_ai_assisted,
    fraction_human: result.fraction_human,
    segments: {
      ai: result.num_ai_segments,
      ai_assisted: result.num_ai_assisted_segments,
      human: result.num_human_segments,
    },
    most_ai_like_passages: passages,
  };
}

async function findSources(text: string, url: string | null, config: Config): Promise<string> {
  const words = countWords(text);
  const result = await pangramFetch(
    config.pangramPlagiarismApiUrl,
    { method: "POST", body: { text, source: "minerval" }, timeoutMs: PLAGIARISM_TIMEOUT_MS },
    config
  );
  await meter("find_sources", words, config.pangramPlagiarismUsdPerWord);
  return JSON.stringify(summarizeSources(result, words, url));
}

/** The plagiarism result, cut down to the sources and how much matched. */
export function summarizeSources(
  result: Record<string, unknown>,
  wordsSent: number,
  url: string | null
): Record<string, unknown> {
  const content = Array.isArray(result.plagiarized_content)
    ? (result.plagiarized_content as unknown[])
    : [];
  const sources = content.slice(0, MAX_SOURCES_RETURNED).map((entry) => {
    if (!entry || typeof entry !== "object") return { match: excerpt(String(entry)) };
    // Keep the source's identity whole and bound any matched text, whatever
    // the field names: the response's per-source shape is not documented.
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(entry as Record<string, unknown>)) {
      out[k] = typeof v === "string" ? (/url|link|title|source/i.test(k) ? v : excerpt(v)) : v;
    }
    return out;
  });
  const sentences = Array.isArray(result.plagiarized_sentences)
    ? (result.plagiarized_sentences as unknown[])
    : [];
  return {
    success: true,
    ...(url ? { url } : {}),
    words_analyzed: wordsSent,
    matches_found: result.plagiarism_detected,
    percent_matching: result.percent_plagiarized,
    total_sentences: result.total_sentences,
    matching_sentences: sentences.length,
    sources,
    ...(content.length > sources.length ? { more_sources: content.length - sources.length } : {}),
  };
}

export interface PangramTools {
  definitions: Tool[];
  /** The tool result, or null when `name` is not a Pangram tool. */
  execute: (name: string, input: Record<string, unknown>) => Promise<string | null>;
}

/**
 * The Pangram tools for one run: no definitions when unconfigured (or when
 * `enabled` is false), and at most `maxCalls` analyses across both tools
 * (0 = uncapped).
 */
export function createPangramTools(opts: {
  maxCalls: number;
  enabled?: boolean;
  config?: Config;
  /** Test hook: the wait between polls. */
  wait?: (ms: number) => Promise<void>;
}): PangramTools {
  const config = opts.config ?? loadConfig();
  const enabled = (opts.enabled ?? true) && pangramConfigured(config);
  const wait = opts.wait ?? sleep;
  let calls = 0;
  return {
    definitions: enabled ? getPangramToolDefinitions(config) : [],
    async execute(name, input) {
      if (!isPangramTool(name)) return null;
      if (!enabled) return failure(`${name} is not in this run's toolset.`);
      if (opts.maxCalls > 0 && calls >= opts.maxCalls) {
        return failure(
          `This run has already made ${calls} Pangram call(s), its cap (${opts.maxCalls}). ` +
            `Work with what those returned.`
        );
      }
      const resolved = await resolveText(input);
      if ("error" in resolved) return failure(resolved.error);
      const text = truncateToWords(resolved.text, config.pangramMaxWords);
      if (countWords(text) === 0) return failure("There is no text to analyze.");
      calls += 1;
      try {
        return name === PANGRAM_CHECK_AI_TOOL_NAME
          ? await checkAi(text, resolved.url, config, wait)
          : await findSources(text, resolved.url, config);
      } catch (err) {
        return failure(
          `Pangram is unavailable (${err instanceof Error ? err.message : String(err)}). ` +
            `Do not retry blindly; proceed with the evidence you have (§20).`
        );
      }
    },
  };
}
